"""Commented source ownership of the allocator predecessor and best-fit lifetime."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xA11A,0xA11C,'data','Allocatore: link che precede il blocco migliore'),(0xA11C,0xA160,'code','Allocazione best fit: scansione e sostituzione anche a parità'),(0xA160,0xA1AF,'code','Allocazione: assorbimento del resto, taglio in coda e azzeramento'),(0xA1AF,0xA1C7,'code','Liberazione di una catena di record'),(0xA1C7,0xA20C,'code','Liberazione: reinserimento ordinato e doppio tentativo di fusione'),(0xA20C,0xA24D,'code','Fusione dei blocchi liberi adiacenti')]
notes={0xA11A:'Word temporanea mutabile. Conserva l’indirizzo del link che porta al candidato scelto:9FE3 se il candidato è la testa, altrimenti precedente+2. Non è l’indirizzo del candidato e non si ricalcola dalla lista finale. A151 la aggiorna per ogni candidato migliore o uguale; release e scansioni senza candidati la conservano. Nessun fallback nei vecchi salvataggi.',0xA121:'La richiesta riguarda il payload: aggiunge tre byte per dimensione e link. I chiamanti ricostruiti usano dimensioni valide entro la capacità del byte.',0xA129:'Prima del primo blocco, IY punta alla word testa della lista libera, non dentro l’arena.',0xA13D:'Bit0 di B indica se è già stato trovato un candidato abbastanza grande. I blocchi troppo piccoli non cancellano il candidato precedente.',0xA149:'Confronta la dimensione del candidato precedente con quella corrente. Salta solo se il precedente è strettamente più piccolo: a parità sceglie l’ULTIMO blocco.',0xA151:'Conserva il link PRECEDENTE al candidato prima che IY diventi il link corrente. Anche una scrittura dello stesso valore è una nuova selezione.',0xA157:'Il link corrente diventa il predecessore del prossimo blocco, anche se il corrente era troppo piccolo o non migliorava il candidato.',0xA160:'Nessun candidato: passa al servizio di memoria esaurita, senza azzerare A11A. Le prove controllate si fermano a C1D8 prima della UI: non certificano la gestione del messaggio di esaurimento.',0xA16D:'Resto = dimensione del candidato meno payload+3.',0xA174:'Resti0..3 non possono formare un nodo libero di quattro byte: assorbe l’intero blocco.',0xA178:'Ricarica il link salvato e lo riscrive per saltare il blocco consumato. Il valore A11A rimane quello selezionato, anche se il suo contenuto cambia.',0xA18A:'Con resto>=4 il blocco libero rimane all’inizio; il record è tagliato dalla CODA.',0xA195:'La dimensione allocata è un byte; il record pubblico punta tre byte dopo l’inizio fisico.',0xA1A0:'Azzera link e payload del record allocato, non l’intera area libera o il resto assorbito.',0xA1AF:'Rilascia una lista: conserva il successore letto dal record corrente prima che la liberazione ne sovrascriva il link.',0xA1C7:'Singolo rilascio: converte il puntatore del payload nell’inizio fisico, poi cerca la posizione ordinata per indirizzo.',0xA1EB:'Collega il blocco liberato fra predecessore e successore; conserva il payload residuo e non modifica A11A.',0xA1F8:'Primo tentativo di fusione dal link precedente. L’esito decide l’indirizzo usato nel secondo tentativo.',0xA1FD:'Quirk originale: se il primo tentativo non fonde, il secondo usa l’inizio del nuovo blocco, non il suo link+2. Il JS conserva questo comportamento; non ripararlo come un allocatore moderno.',0xA20C:'Fonde solo quando fine del blocco corrente e inizio del successivo coincidono esattamente.',0xA23D:'Somma le dimensioni word e collega il successore del blocco assorbito. Non azzera il suo payload né il temporaneo A11A.'}
lines=['; Analisi offline, dati distinti dal codice; nessuna esecuzione Z80 nel motore JS.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=b-at;op='DEFB '+','.join(f'${v:02X}'for v in m[at:b])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/allocation-link';root.mkdir(exist_ok=True)
(root/'allocation-link.asm').write_text('\n'.join(lines)+'\n')
(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=122 if k=='data'else 92,**({'fields':[['A11A–A11B','2 byte','Indirizzo del link predecessore del candidato migliore'],['Persistenza','mutabile','Si aggiorna a ogni candidato migliore o uguale; release e fallimento senza candidati lo conservano']]}if k=='data'else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
